mapper.select:
SELECT COUNT(*)
FROM xa_touch_custom_worklogs w
INNER JOIN TOUCH_TASK t ON t.worklog_id = w.workLogId
WHERE t.cust_id = #{custId}
  AND w.createTime >= #{startTime}
  AND w.createTime < #{endTime}
  AND (w.isDestroy IS NULL
       OR (w.isDestroy <> '1' AND w.isDestroy <> 'Y' AND w.isDestroy <> 'TRUE'))
